    // --- Circular reference safety tests ---

    #[test]
    fn transitive_dependents_does_not_loop_on_two_node_cycle() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec!["b".to_string()])
            .add_step("b", vec!["a".to_string()])
            .build()
            .unwrap();

        let deps = graph.transitive_dependents("a");
        assert!(deps.contains("b"));
        // "a" depends on "b" and "b" depends on "a", so "a" is a transitive dependent of itself
        assert!(deps.contains("a"));
    }

    #[test]
    fn transitive_dependents_does_not_loop_on_three_node_cycle() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec!["c".to_string()])
            .add_step("b", vec!["a".to_string()])
            .add_step("c", vec!["b".to_string()])
            .build()
            .unwrap();

        let deps = graph.transitive_dependents("a");
        assert!(deps.contains("a"));
        assert!(deps.contains("b"));
        assert!(deps.contains("c"));
    }

    #[test]
    fn transitive_dependents_does_not_loop_on_self_cycle() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec!["a".to_string()])
            .build()
            .unwrap();

        let deps = graph.transitive_dependents("a");
        assert!(deps.contains("a"));
    }

    #[test]
    fn transitive_dependents_nonexistent_step_returns_empty() {
        let graph = DependencyGraph::builder()
            .add_step("a", vec![])
            .build()
            .unwrap();

        let deps = graph.transitive_dependents("nonexistent");
        assert!(deps.is_empty());
    }

